CREATE TABLE "meal_entries" ("created_at_utc" INTEGER NOT NULL, "updated_at_utc" INTEGER NOT NULL, "row_version" INTEGER NOT NULL DEFAULT 1 CHECK(row_version >= 1), "deleted_at_utc" INTEGER NULL, "id" TEXT NOT NULL, "name" TEXT NOT NULL CHECK(length(name) BETWEEN 1 AND 80), "kcal" INTEGER NULL CHECK(kcal IS NULL OR kcal BETWEEN 0 AND 5000), "occurred_at_utc" INTEGER NOT NULL, "local_date" TEXT NOT NULL, "timezone_id" TEXT NOT NULL, "note" TEXT NULL CHECK(note IS NULL OR length(note) <= 500), PRIMARY KEY ("id"));
