CREATE TABLE "tasks" ("created_at_utc" INTEGER NOT NULL, "updated_at_utc" INTEGER NOT NULL, "row_version" INTEGER NOT NULL DEFAULT 1 CHECK(row_version >= 1), "deleted_at_utc" INTEGER NULL, "id" TEXT NOT NULL, "title" TEXT NOT NULL CHECK(length(title) BETWEEN 1 AND 120), "description" TEXT NULL CHECK(description IS NULL OR length(description) <= 1000), "priority" TEXT NOT NULL DEFAULT 'normal' CHECK(priority IN ('low','normal','high')), "due_local_date" TEXT NULL, "tags_json" TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(tags_json)), "completed_at_utc" INTEGER NULL, "completed_local_date" TEXT NULL, "timezone_id" TEXT NULL, "completion_eligibility" INTEGER NULL CHECK ("completion_eligibility" IN (0, 1)), PRIMARY KEY ("id"), CHECK ((completed_at_utc IS NULL) = (completed_local_date IS NULL)), CHECK ((completed_at_utc IS NULL) = (completion_eligibility IS NULL)));
